PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<WireCacheChecksumAlgorithm>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<WireCacheEvictionPolicy>(enum_arg_value));
      }
    case 131: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<WireCacheResultSource>(enum_arg_value));
      }
    case 132: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<WireCacheTransferState>(enum_arg_value));
      }
    case 133: {
        return CustomEncodableValue(WireCacheManagerConfig::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(WireCacheRequest::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(WireCacheEntry::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 136: {
        return CustomEncodableValue(WireCacheFetchResult::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 137: {
        return CustomEncodableValue(WireCacheProgressEvent::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 138: {
        return CustomEncodableValue(WireCacheStats::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 139: {
        return CustomEncodableValue(WireCachePlatformCapabilities::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(WireCacheChecksumAlgorithm)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<WireCacheChecksumAlgorithm>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheEvictionPolicy)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<WireCacheEvictionPolicy>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheResultSource)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<WireCacheResultSource>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheTransferState)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<WireCacheTransferState>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheManagerConfig)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<WireCacheManagerConfig>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheRequest)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<WireCacheRequest>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheEntry)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<WireCacheEntry>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheFetchResult)) {
      stream->WriteByte(136);
      WriteValue(EncodableValue(std::any_cast<WireCacheFetchResult>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheProgressEvent)) {
      stream->WriteByte(137);
      WriteValue(EncodableValue(std::any_cast<WireCacheProgressEvent>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCacheStats)) {
      stream->WriteByte(138);
      WriteValue(EncodableValue(std::any_cast<WireCacheStats>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(WireCachePlatformCapabilities)) {
      stream->WriteByte(139);
      WriteValue(EncodableValue(std::any_cast<WireCachePlatformCapabilities>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

